using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the value of a configuration key")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app.name"] = "MyService",
            ["app.version"] = "1.0.0",
            ["app.environment"] = "production",
            ["app.max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the full application configuration as JSON",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            app = new
            {
                name = "MyService",
                version = "1.0.0",
                environment = "production",
                maxConnections = 100,
                features = new { caching = true, logging = true, metrics = false }
            }
        };

        return System.Text.Json.JsonSerializer.Serialize(settings,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "Configuration Section",
        Description = "Returns a specific configuration section")]
    public static string GetConfigSection(
        [Description("The configuration section name (e.g., 'features', 'limits')")] string section)
    {
        var sections = new Dictionary<string, object>
        {
            ["features"] = new { caching = true, logging = true, metrics = false },
            ["limits"] = new { maxConnections = 100, timeoutSeconds = 30, maxRetries = 3 }
        };

        if (!sections.TryGetValue(section, out var data))
            return $"{{\"error\": \"Unknown section: {section}\"}}";

        return System.Text.Json.JsonSerializer.Serialize(data,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

