using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer.Tools;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "Application Settings",
        MimeType = "application/json")]
    [System.ComponentModel.Description("Returns the full application configuration as JSON")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            app = new
            {
                name = "MyService",
                version = "1.0.0",
                environment = "production",
                maxConnections = 100,
                features = new { caching = true, logging = true, metrics = false }
            }
        };

        return JsonSerializer.Serialize(settings,
            new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "Configuration Section",
        MimeType = "application/json")]
    [System.ComponentModel.Description("Returns a specific configuration section")]
    public static string GetConfigSection(string section)
    {
        var sections = new Dictionary<string, object>
        {
            ["features"] = new { caching = true, logging = true, metrics = false },
            ["limits"] = new { maxConnections = 100, timeoutSeconds = 30, maxRetries = 3 }
        };

        if (!sections.TryGetValue(section, out var data))
            return $"{{\"error\": \"Unknown section: {section}\"}}";

        return JsonSerializer.Serialize(data,
            new JsonSerializerOptions { WriteIndented = true });
    }
}

